package com.moyolearn.museopticalprobe;
public final class UnmodifiedTrialPhaseTest {
 public static void main(String[] args){if(!UnmodifiedTrialPhase.phase(0).equals("baseline-pen-out")||!UnmodifiedTrialPhase.phase(4999999999L).equals("baseline-pen-out")||!UnmodifiedTrialPhase.phase(5000000000L).equals("requested-pen-motion")||!UnmodifiedTrialPhase.phase(14999999999L).equals("requested-pen-motion")||!UnmodifiedTrialPhase.phase(15000000000L).equals("return-pen-out")||!UnmodifiedTrialPhase.phase(19999999999L).equals("return-pen-out")||!UnmodifiedTrialPhase.phase(20000000000L).equals("complete"))throw new AssertionError("Phase boundary");if(UnmodifiedTrialPhase.remainingSeconds(0)!=20||UnmodifiedTrialPhase.remainingSeconds(5000000000L)!=15||UnmodifiedTrialPhase.remainingSeconds(19999999999L)!=1||UnmodifiedTrialPhase.remainingSeconds(20000000000L)!=0)throw new AssertionError("Remaining time");try{UnmodifiedTrialPhase.phase(-1);throw new AssertionError("Negative accepted");}catch(IllegalArgumentException expected){}System.out.println("PASS: nominal UI cue phase boundaries and remaining seconds; not physical action verification");}
}
